INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7394532, 1162727, 180777, '<td valign="top">Beautiful! Contrasts, color, composition. The reflections, intimacy caught in silhette.</td>', 'Beautiful! Contrasts, color, composition. The reflections, intimacy caught in silhette.', '2015-08-03 01:25:46.000000', NULL, 1),
(7394533, 1163039, 180777, '<td valign="top">I am new to photography and can appreciate how challenging it is to get a good moonshot with clear trees or other things in the foreground. this also has a very nice balance to it</td>', 'I am new to photography and can appreciate how challenging it is to get a good moonshot with clear trees or other things in the foreground. this also has a very nice balance to it', '2015-08-03 01:27:37.000000', NULL, 1),
(7394537, 1162965, 180777, '<td valign="top">Okay so I like this because I know how hard it is to shoot the moon at night with trees in the foreground. You actually were able to capture the foreground lighting really well - better than I was able to. And you did it without horribly overexposing the moon. I would say, do a foreground shot to capture more light and clarity, and then *instantly* snap the moon, also in perfect focus, and at a much faster shutter speed and lower ISO (i.e. 1/250+ and 100 - 200 ISO) while at the same time using an F number between 3.2 and 5.6. But this might take two cameras! Or super Speedo-Gonzales fingers that no one in reality posesses. Thanks for sharing.</td>', 'Okay so I like this because I know how hard it is to shoot the moon at night with trees in the foreground. You actually were able to capture the foreground lighting really well - better than I was able to. And you did it without horribly overexposing the moon. I would say, do a foreground shot to capture more light and clarity, and then *instantly* snap the moon, also in perfect focus, and at a much faster shutter speed and lower ISO (i.e. 1/250+ and 100 - 200 ISO) while at the same time using an F number between 3.2 and 5.6. But this might take two cameras! Or super Speedo-Gonzales fingers that no one in reality posesses. Thanks for sharing.', '2015-08-03 01:48:31.000000', NULL, 1),
(7394562, 1162954, 352, '<td valign="top">To me a silhouette does not have discernible facial features; feel like the boy is too lit for a silhouette.</td>', 'To me a silhouette does not have discernible facial features; feel like the boy is too lit for a silhouette.', '2015-08-03 02:29:09.000000', NULL, 1),
(7394563, 1162993, 352, '<td valign="top">The levels adjustment on this is a bit distracting where there are almost floating objects in the white.</td>', 'The levels adjustment on this is a bit distracting where there are almost floating objects in the white.', '2015-08-03 02:30:27.000000', NULL, 1),
(7394564, 1163044, 352, '<td valign="top">Too long of an exposure here; seems much too bright to be considered night.</td>', 'Too long of an exposure here; seems much too bright to be considered night.', '2015-08-03 02:31:19.000000', NULL, 1),
(7394565, 1162958, 352, '<td valign="top">How did you do the circles affect in advanced editing rules?</td>', 'How did you do the circles affect in advanced editing rules?', '2015-08-03 02:32:14.000000', NULL, 1),
(7394566, 1163042, 352, '<td valign="top">Not a fan of the blur effect you applied to the foreground.</td>', 'Not a fan of the blur effect you applied to the foreground.', '2015-08-03 02:32:52.000000', NULL, 1),
(7394567, 1163048, 352, '<td valign="top">subjects in foreground are a bit too brightly lit to be silhouettes.</td>', 'subjects in foreground are a bit too brightly lit to be silhouettes.', '2015-08-03 02:34:05.000000', NULL, 1),
