(7394697, 1163023, 163081, '<td valign="top">Stargate. Really cool picture to look at. A 10 from me</td>', 'Stargate. Really cool picture to look at. A 10 from me', '2015-08-03 11:59:41.000000', NULL, 1),
(7394698, 1162958, 163081, '<td valign="top">Ribbon winner. Hopefully my 10 will help to get it :)</td>', 'Ribbon winner. Hopefully my 10 will help to get it :)', '2015-08-03 12:00:32.000000', NULL, 1),
(7394720, 1163000, 180777, '<td valign="top">I love the focus and deep colors; the silhouettes are keeping w/theme, and they look (abstractly) to me like a field of celebration under the blue moon. But the vignette is too strong in my opinion (I''m new to this! so please take my opinion in view of that) The vignette is too much, and it also covers up some foreground shadows and blacks that you might have been able to highlight with a transverse filter. The moon in this image, I feel it is appropriate for the image. Do you have any pix of the grass being blurry, with the moon being in focus? How would you achieve that? <br/> <br/>Thanks for sharing!</td>', 'I love the focus and deep colors; the silhouettes are keeping w/theme, and they look (abstractly) to me like a field of celebration under the blue moon. But the vignette is too strong in my opinion (I''m new to this! so please take my opinion in view of that) The vignette is too much, and it also covers up some foreground shadows and blacks that you might have been able to highlight with a transverse filter. The moon in this image, I feel it is appropriate for the image. Do you have any pix of the grass being blurry, with the moon being in focus? How would you achieve that?  Thanks for sharing!', '2015-08-03 13:40:43.000000', NULL, 1),
(7394794, 1162996, 96915, '<td valign="top">Excellent silhouette, and I love the depth in the clouds</td>', 'Excellent silhouette, and I love the depth in the clouds', '2015-08-03 19:49:01.000000', NULL, 1),
(7394810, 1162954, 97225, '<td valign="top">Nice photo, not a silhouette.</td>', 'Nice photo, not a silhouette.', '2015-08-03 21:53:43.000000', NULL, 1),
